import math
    import random
    import time

    LANGUAGE_WRAPPER = 'In a math contest, consider integers [a] > [b] > 0 and a fixed angle shift [phi_deg] (in degrees). Among the complex numbers z on the unit circle satisfying z^[a] = z^[b] + e^{i [phi_deg]}, write z_m = cos(theta_m) + i sin(theta_m) with 0 <= theta_1 < theta_2 < ... < theta_[total_count] < 360, where angles are measured in degrees and thetas are sorted increasingly. Let [d] = 2. Compute the sum of all theta_j whose index j is congruent to [r] modulo [d] (that is, theta_[r] + theta_[r + d] + theta_[r + 2d] + ... up to j <= [total_count]).'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
# We construct parameters so the unit-circle solutions form two interleaving arithmetic progressions
# and the angle-matching constraint selects exactly half of each, giving total_count = b.
# Strategy: pick b even, k a multiple of 3, set a = ((2*k+1)*b)//2 (ensuring integer), and phi = 0.
# Then both c=120 and c=600 branches with s=0 survive; s=1 branches fail. Valid solutions come from even k' only.
while True:
    b_choices = [x for x in range(8, 41) if x % 2 == 0]
    b = rng.choice(b_choices)
    k = rng.choice([3, 6, 9])
    a = ((2*k + 1) * b) // 2
    # Ensure a > b and integer
    if a <= b:
        continue
    phi_deg = 0  # simplest robust choice; keeps formulas clean and guarantees constraints
    # Index modulus and residue
    d = 2
    r = rng.choice([1, 2])
    total_count = b  # proven under our parameterization
    # Sanity check: ensure generated parameters satisfy structural constraints used by verifier
    # 2a - b = 2kb, with k multiple of 3; phi condition trivial as phi=0
    if (2*a - b) % (2*b) != 0:
        continue
    k_check = (2*a - b) // (2*b)
    if k_check % 3 != 0:
        continue
    # Good assignment
    return {'a': a, 'b': b, 'phi_deg': phi_deg, 'total_count': total_count, 'd': d, 'r': r}

    def verifier(assign):
# Validate and compute the sum via the derived closed-form.
try:
    a = int(assign['a'])
    b = int(assign['b'])
    phi_deg = int(assign['phi_deg'])
    total_count = int(assign['total_count'])
    d = int(assign['d'])
    r = int(assign['r'])
except Exception:
    # Missing or malformed fields
    return (False, None)
# Domain checks
if not (b > 0 and a > b):
    # a must exceed b
    return (False, None)
if b % 2 != 0:
    # We rely on b even for the progression structure
    return (False, None)
if d != 2 or r not in (1, 2):
    return (False, None)
if not (0 <= phi_deg <= 360):
    return (False, None)
# Structural constraints to ensure the intended configuration holds
if (2*a - b) % (2*b) != 0:
    # Must be of the form 2a - b = 2k b
    return (False, None)
k = (2*a - b) // (2*b)
if k % 3 != 0:
    # Ensures c in {120,600} branches work and {240,480} don't, yielding exactly b unit-circle solutions
    return (False, None)
if total_count != b:
    # Under our setup, the count of unit-circle roots in [0,360) should equal b
    return (False, None)
# Closed-form for the sum of indices congruent to r mod 2:
# Valid solutions split into two arithmetic progressions of step 720/b:
# P0: base0 = (phi + 120)/b, j = 0..(b/2 - 1) -> odd indices
# P1: base1 = (phi + 600)/b, j = 0..(b/2 - 1) -> even indices
# Summation over each progression (already reduced to [0,360) by construction) gives:
# S_odd  = (phi + 120)/2 + 90*(b - 2)
# S_even = (phi + 600)/2 + 90*(b - 2)
if r == 1:
    answer = (phi_deg + 120) / 2 + 90 * (b - 2)
else:
    answer = (phi_deg + 600) / 2 + 90 * (b - 2)
# The sum is integer for phi_deg integer; enforce integer output
if abs(answer - round(answer)) < 1e-9:
    answer = int(round(answer))
return (True, answer)


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

